const MAX_BODY_BYTES = 300_000
type Access = { workspace: CompanyWorkspaceRecord; role: "owner" | "admin" | "member"; evidenceId: string | null }
export type StagingDatabase = WorkspaceDatabase & {
  hasStagingAccess(userId: string): Promise<boolean>
  findStagingWorkspaceForUser(userId: string): Promise<Access | null>
  checkReadiness(): Promise<{ profile: string; schemaVersion: number; legacyContainmentVerified?: boolean }>
}

export interface StagingLog {
  event: "request"
  requestId: string
  route: "health" | "ready" | "config" | "session" | "workspace" | "asset" | "unknown"
  status: number
  durationMs: number
}

export interface StagingOverrides {
  database?: StagingDatabase
  validateUser?: (token: string) => Promise<AuthenticatedUser | null>
  verifyAssets?: () => Promise<void>
  serveAsset?: (pathname: string) => Promise<Response | null>
  log?: (event: StagingLog) => void
}

function json(status: number, value: unknown) { return Response.json(value, { status }) }

async function boundedRequest(request: Request, url: URL): Promise<Request> {
  const claimed = request.headers.get("content-length")
  if (claimed && (!/^\d+$/.test(claimed) || Number(claimed) > MAX_BODY_BYTES)) throw new Error("Request too large.")
  if (!request.body) return new Request(url, request)
  const reader = request.body.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      total += value.byteLength
      if (total > MAX_BODY_BYTES) { await reader.cancel(); throw new Error("Request too large.") }
      chunks.push(value)
    }
  } finally { reader.releaseLock() }
  const body = new Uint8Array(total)
  let position = 0
  for (const chunk of chunks) { body.set(chunk, position); position += chunk.byteLength }
  return new Request(url, { method: request.method, headers: request.headers, body, signal: request.signal })
}

/** No listener, migration or credential read occurs at import time. */
export async function createStagingServer(config: StagingConfig, overrides: StagingOverrides = {}) {
  if (config.profile !== STAGING_PROFILE) throw new Error("Private staging profile is invalid.")
  const database: StagingDatabase = overrides.database ?? await HostedWorkspaceDatabase.create({ connectionString: config.databaseUrl, expectedProjectRef: config.projectRef, reuseExistingProject: config.reuseExistingProject, tlsCaPem: await loadStagingDatabaseCa({ caPem: config.databaseCaPem, caFile: config.databaseCaFile }) })
  const auth = overrides.validateUser ?? (() => {
    const boundedFetch = ((input: RequestInfo | URL, init?: RequestInit) => fetch(input, { ...init, signal: AbortSignal.timeout(5_000) })) as typeof fetch
    const client = createClient(config.supabaseUrl, config.supabaseAnonKey, { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false }, global: { fetch: boundedFetch } })
    return (token: string) => validateUserFromToken(token, client)
  })()
  const checkAssets = overrides.verifyAssets ?? (() => verifyStagingAssets(config.webRoot))
  const serveAsset = overrides.serveAsset ?? ((pathname: string) => serveStagingAsset(config.webRoot, pathname))
  const log = overrides.log ?? ((event: StagingLog) => console.info(JSON.stringify(event)))
  const admission = createRateLimiter({ max: 360, windowMs: 60_000, maxBuckets: 1 })
  const actors = createRateLimiter({ max: 120, windowMs: 60_000, maxBuckets: 100 })
  const validateUser = async (token: string) => {
    const user = await auth(token)
    return user && await database.hasStagingAccess(user.id) ? user : null
  }
  const routes = createWorkspaceRoutes({
    allowedOrigins: [config.origin], validateUser,
    store: createWorkspaceStore(database, async (userId) => {
      const access = await database.findStagingWorkspaceForUser(userId)
      if (!access || access.role !== "owner") throw new Error("Workspace not found.")
      return access.workspace
    }),
  })
  const corporateInventoryRoutes=createCorporateInventoryRoutes({database,validateUser,origin:config.origin})
  const stationaryGasRoutes=createM73Routes({database,validateUser,origin:config.origin,authority:createM73Authority()})
  const controlledFleetRoutes=createM75Routes({database,validateUser,origin:config.origin,authority:createM74Authority()})
  const mobileDieselRoutes=createM74Routes({database,validateUser,origin:config.origin,authority:createM74Authority()})
  const annualEvidenceRoutes=createAnnualEvidenceRoutes({database,validateUser,origin:config.origin})
  const annualEvidenceReportRoutes=createAnnualEvidenceReportRoutes({database,validateUser,origin:config.origin})
  const annualWorksheetRoutes=createAnnualWorksheetRoutes({database,validateUser,origin:config.origin})
  const annualReportRoutes=createAnnualWorksheetReportRoutes({database,validateUser,origin:config.origin})
  const sourceWorksheetRoutes=createSourceWorksheetRoutes({database,validateUser,origin:config.origin})
  const sourceReportRoutes=createSourceWorksheetReportRoutes({database,validateUser,origin:config.origin})
  const electricitySourceRoutes=createElectricitySourceRoutes({database,validateUser,origin:config.origin})
  const reportRoutes = createWorksheetReportRoutes({ database, validateUser, origin: config.origin })
  const worksheetRoutes = createWorksheetRoutes({ database, validateUser, origin: config.origin })
  const databaseReadiness = async () => {
    const receipt = await database.checkReadiness()
    if (receipt.profile !== STAGING_PROFILE || receipt.schemaVersion !== 18) throw new Error("Staging database unavailable.")
    if (config.projectRef === "icockcoguyadhryzydvl" && (!config.reuseExistingProject || receipt.legacyContainmentVerified !== true)) throw new Error("Existing project containment unavailable.")
    return receipt
  }
  const readiness = async () => { const receipt = await databaseReadiness(); await checkAssets(); return receipt }
  try { await readiness() } catch { await database.close(); throw new Error("Private staging dependencies are unavailable.") }

  const routeName = (pathname: string): StagingLog["route"] => pathname === "/health" ? "health" : pathname === "/ready" ? "ready" : pathname === "/workspace-api/config" ? "config" : pathname === "/workspace-api/session" ? "session" : pathname.startsWith("/workspace-api/workspace") ? "workspace" : pathname === "/" || pathname === "/workspace" || pathname.startsWith("/assets/") ? "asset" : "unknown"

  async function dispatch(request: Request): Promise<Response> {
    const url = new URL(request.url)
    const isGet = request.method === "GET"
    if (url.pathname === "/health" && isGet) return json(200, { status: "alive" })
    if (url.pathname === "/ready" && isGet) {
      try { const receipt = await readiness(); return json(200, { status: "ready", ...receipt }) }
      catch { return json(503, { status: "unavailable" }) }
    }
    if (url.pathname.startsWith("/workspace-api/")) {
      const origin = request.headers.get("origin")
      if ((origin && origin !== config.origin) || (!isGet && origin !== config.origin)) return json(403, { error: "Forbidden." })
      if (!admission.check("staging").allowed) return json(429, { error: "Request limit reached." })
      if (config.projectRef === "icockcoguyadhryzydvl") await databaseReadiness()
      if (url.pathname === "/workspace-api/config" && isGet) return json(200, { profile: STAGING_PROFILE, supabaseUrl: config.supabaseUrl, anonKey: config.supabaseAnonKey })
      const token = extractBearerToken(request.headers)
      if (!token || token.length > 8192) return json(401, { error: "Authentication required." })
      let user: AuthenticatedUser | null
      try { user = await auth(token) } catch { return json(503, { error: "Authentication is unavailable." }) }
      if (!user) return json(401, { error: "Authentication required." })
      if (!actors.check(user.id).allowed) return json(429, { error: "Request limit reached." })
      if (!await database.hasStagingAccess(user.id)) return json(403, { error: "Private staging access required." })
      if (url.pathname === "/workspace-api/session" && isGet) {
        const access = await database.findStagingWorkspaceForUser(user.id)
        if (!access) return json(403, { error: "Private staging access required." })
        return json(200, { profile: STAGING_PROFILE, user: { id: user.id }, access: { role: access.role, workspaceId: access.workspace.id, evidenceId: access.evidenceId } })
      }
      url.pathname = url.pathname.slice("/workspace-api".length)
      let forwarded: Request
      try { forwarded = await boundedRequest(request, url) } catch { return json(413, { error: "Request too large." }) }
      if (url.pathname.includes("/corporate-inventories")) return corporateInventoryRoutes(forwarded)
      if (url.pathname.includes("/stationary-natural-gas")) return stationaryGasRoutes(forwarded)
      if (url.pathname.includes("/controlled-fleet")) return controlledFleetRoutes(forwarded)
      if (url.pathname.includes("/mobile-diesel")) return mobileDieselRoutes(forwarded)
      if (url.pathname.includes("/annual-electricity-evidence/reports")) return annualEvidenceReportRoutes(forwarded)
      if (url.pathname.includes("/annual-electricity-evidence")) return annualEvidenceRoutes(forwarded)
      if (url.pathname.includes("/annual-electricity-worksheet/reports")) return annualReportRoutes(forwarded)
      if (url.pathname.includes("/annual-electricity-worksheet")) return annualWorksheetRoutes(forwarded)
      if (url.pathname.includes("/source-electricity-worksheet/sources")) return electricitySourceRoutes(forwarded)
      if (url.pathname.includes("/source-electricity-worksheet/reports")) return sourceReportRoutes(forwarded)
      if (url.pathname.includes("/source-electricity-worksheet")) return sourceWorksheetRoutes(forwarded)
      if (url.pathname.includes("/electricity-worksheet/reports")) return reportRoutes(forwarded)
      if (url.pathname.includes("/electricity-worksheet")) return worksheetRoutes(forwarded)
      return routes.handle(forwarded)
    }
    if (isGet) return await serveAsset(url.pathname) ?? json(404, { error: "Not found." })
    return json(404, { error: "Not found." })
  }

  return {
    async fetch(request: Request) {
      const started = performance.now()
      const requestId = crypto.randomUUID()
      let response: Response
      try { response = await dispatch(request) } catch { response = json(503, { error: "Private staging is unavailable." }) }
      const headers = new Headers(response.headers)
      headers.set("cache-control", "no-store")
      headers.set("x-request-id", requestId)
      headers.set("x-content-type-options", "nosniff")
      headers.set("referrer-policy", "no-referrer")
      headers.set("x-frame-options", "DENY")
      if (!headers.has("content-security-policy")) headers.set("content-security-policy", `default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self' ${config.supabaseUrl}; img-src 'self' data:; base-uri 'none'; frame-ancestors 'none'; form-action 'self'; object-src 'none'`)
      if (config.origin.startsWith("https:")) headers.set("strict-transport-security", "max-age=31536000")
      try { log({ event: "request", requestId, route: routeName(new URL(request.url).pathname), status: response.status, durationMs: Math.round(performance.now() - started) }) } catch { /* Log failures cannot disclose request contents or turn a committed write into a client failure. */ }
      return new Response(response.body, { status: response.status, headers })
    },
    close: () => database.close(),
  }
}

if (import.meta.main) {
  try {
    const config = readStagingConfig()
    const app = await createStagingServer(config)
    const server = Bun.serve({ hostname: "0.0.0.0", port: config.port, maxRequestBodySize: MAX_BODY_BYTES, idleTimeout: 30, fetch: app.fetch })
    const shutdown = async () => { await server.stop(); await app.close(); process.exit(0) }
    process.once("SIGINT", shutdown)
    process.once("SIGTERM", shutdown)
    console.info(JSON.stringify({ event: "staging_started", profile: STAGING_PROFILE }))
  } catch {
    console.error(JSON.stringify({ event: "staging_start_failed" }))
    process.exitCode = 1
  }
}

import {M75ValidationError,m71Uuid,m75Export,parseM71Json,validateM75Report,validateM75Review,validateM75Save,type M74Authority,type M75Register,type M75Report,type M75ReportInput,type M75ReportProof,type M75Review,type M75ReviewInput,type M75SaveInput,type M75Version} from '@neuvetra/database'
import {extractBearerToken,type AuthenticatedUser} from '../lib/auth'
type Database={canManageWorkspace(userId:string,companyId:string):Promise<boolean>;findControlledFleet(userId:string,companyId:string,authority:M74Authority):Promise<M75Register|null>;saveControlledFleet(userId:string,companyId:string,rosterId:string|null,input:M75SaveInput,authority:M74Authority):Promise<M75Version>;reviewControlledFleet(userId:string,companyId:string,rosterId:string,input:M75ReviewInput,authority:M74Authority):Promise<M75Review>;createControlledFleetReport(userId:string,companyId:string,rosterId:string,input:M75ReportInput,authority:M74Authority):Promise<M75Report>;findControlledFleetReport(userId:string,companyId:string,rosterId:string,reportId:string,authority:M74Authority):Promise<M75Report|null>;findControlledFleetReportProof(userId:string,companyId:string,rosterId:string,reportId:string,authority:M74Authority):Promise<M75ReportProof|null>}
export function createM75Routes(deps:{database:Database;validateUser:(token:string)=>Promise<AuthenticatedUser|null>;origin:string;authority:M74Authority}){
 return async(request:Request):Promise<Response>=>{const respond=(status:number,body:unknown)=>Response.json(body,{status,headers:{'cache-control':'no-store'}}),match=/^\/workspace\/([^/]+)\/controlled-fleet(?:\/([^/]+)\/(versions|reviews|reports|statements)(?:\/([^/]+)(?:\/(roster-export|download|snapshot|proof))?)?)?$/.exec(new URL(request.url).pathname);if(!match||!m71Uuid(match[1])||(match[2]&&!m71Uuid(match[2]))||(match[4]&&!m71Uuid(match[4])))return respond(404,{error:'Controlled-fleet record not found.'});const [,company,roster,action,id,operation]=match,origin=request.headers.get('origin');if((request.method!=='GET'&&origin!==deps.origin)||(origin&&origin!==deps.origin))return respond(403,{error:'Forbidden.'});const token=extractBearerToken(request.headers);if(!token)return respond(401,{error:'Authentication required.'});const actor=await deps.validateUser(token);if(!actor)return respond(401,{error:'Authentication required.'});try{const register=await deps.database.findControlledFleet(actor.id,company!,deps.authority);if(!register)return respond(404,{error:'Controlled-fleet record not found.'});if(roster&&register.rosterId!==roster)return respond(404,{error:'Controlled-fleet record not found.'});if(request.method==='GET'){if(!action)return respond(200,register);const headers={'cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'no-referrer'};if(action==='versions'&&id){const v=register.versions.find(x=>x.id===id);if(!v)return respond(404,{error:'Roster version not found.'});if(!operation)return respond(200,v);if(operation==='roster-export')return new Response(m75Export(v),{headers:{...headers,'content-type':'application/json; charset=utf-8','content-disposition':`attachment; filename="synthetic-controlled-fleet-v${v.version}.json"`}})}if(action==='statements'&&id&&operation==='download'){const s=register.versions.map(v=>v.statement).find(x=>x?.id===id);if(s)return new Response(s.text,{headers:{...headers,'content-type':'text/plain; charset=utf-8','content-disposition':'attachment; filename="synthetic-controlled-fleet-roster.txt"'}})}if(action==='reports'&&id){const report=await deps.database.findControlledFleetReport(actor.id,company!,roster!,id,deps.authority);if(!report)return respond(404,{error:'Fleet report not found.'});if(operation==='download')return new Response(report.html,{headers:{...headers,'content-type':'text/html; charset=utf-8','content-disposition':'attachment; filename="synthetic-controlled-fleet-report.html"','content-security-policy':"default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'; sandbox allow-modals"}});if(operation==='snapshot')return new Response(report.snapshotJson,{headers:{...headers,'content-type':'application/json; charset=utf-8','content-disposition':'attachment; filename="synthetic-controlled-fleet-report-snapshot.json"'}});if(operation==='proof')return respond(200,await deps.database.findControlledFleetReportProof(actor.id,company!,roster!,id,deps.authority))}return respond(404,{error:'Controlled-fleet record not found.'})}
 if(request.method!=='POST'||id||operation)return respond(405,{error:'Method not allowed.'});if(!await deps.database.canManageWorkspace(actor.id,company!))return respond(403,{error:'Forbidden.'});let body:unknown;try{body=parseM71Json(await request.text(),262144)}catch{return respond(422,{error:'Invalid controlled-fleet JSON request.'})}if(action==='reviews'&&roster)return respond(201,await deps.database.reviewControlledFleet(actor.id,company!,roster,validateM75Review(body),deps.authority));if(action==='reports'&&roster)return respond(201,await deps.database.createControlledFleetReport(actor.id,company!,roster,validateM75Report(body),deps.authority));if(action&&action!=='versions')return respond(404,{error:'Controlled-fleet record not found.'});const input=validateM75Save(body);if(Boolean(roster)!==Boolean(input.expectedVersionId))return respond(422,{error:'Exact correction version binding required.'});return respond(201,await deps.database.saveControlledFleet(actor.id,company!,roster??null,input,deps.authority))}catch(e){if(e instanceof M75ValidationError)return respond(422,{error:e.message});const code=(e as {code?:string})?.code;if(['22023','22P02','22007','22008','22003'].includes(code??''))return respond(422,{error:'Invalid or unsupported controlled-fleet request.'});if(code==='23505')return respond(409,{error:'Roster, dependency, review, report or request changed. Reload current fleet reconciliation.'});if(code==='42501')return respond(403,{error:'Forbidden.'});if(code==='54000'||code==='54001')return respond(422,{error:'Synthetic fleet history capacity reached. Earlier records remain readable.',code:'history_limit'});return respond(503,{error:'Controlled-fleet records could not be verified.'})}}
}

import { useEffect, useLayoutEffect, useRef, useState, type RefObject } from 'react'
import type { HostedWorkspaceActor } from '@/lib/workspace-api'
import { FleetRosterEditor } from './FleetRosterEditor'
import { newFleetStatement } from '@/lib/m75-form'
import { M75_PROFILE, M75_PERIOD, M75_LIMITATIONS, type M75Register, type M75StatementInput, type M75Link, type M75ReviewInput, type M75ReportMetadata } from '../../../../packages/neuvetra-database/src/m75-contract'
import { m75CanonicalJson, validateM75Save } from '../../../../packages/neuvetra-database/src/m75-validation'
import { m75ReportSnapshot } from '../../../../packages/neuvetra-database/src/m75-report'
import { coverageSha256 } from '@/lib/m71-api'
import { fleetRegisterRequest, fleetSaveRequest, fleetReviewRequest, fleetReportRequest, fleetReportDownload, fleetReportSnapshotDownload, fleetStatementDownload, fleetVersionDownload } from '@/lib/m75-api'

const words = (value: string) => value.replace(/_/g, ' ')
function download(text: string, name: string, type: string) { const url = URL.createObjectURL(new Blob([text], { type })); const link = document.createElement('a'); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }

export function ControlledFleet({ actor, workspaceId, headingRef, onNavigate }: { actor: HostedWorkspaceActor; workspaceId: string | null; headingRef: RefObject<HTMLHeadingElement | null>; onNavigate: (panel: 'corporate' | 'mobile') => void }) {
  const [scope, setScope] = useState({ actor, workspaceId }), [register, setRegister] = useState<M75Register | null>(null), [selectedId, setSelectedId] = useState('')
  const [statement, setStatement] = useState<M75StatementInput>(newFleetStatement), [links, setLinks] = useState<M75Link[]>([]), [editing, setEditing] = useState(false), [confirmed, setConfirmed] = useState(false), [reason, setReason] = useState('')
  const [busy, setBusy] = useState(true), [error, setError] = useState(false), [message, setMessage] = useState('Loading fleet records…')
  const [decision, setDecision] = useState<M75ReviewInput['decision']>('changes_requested'), [reviewNote, setReviewNote] = useState(''), [ack, setAck] = useState(false), [currentReportHash, setCurrentReportHash] = useState('')
  const life = useRef({ scope, active: true }), lock = useRef(false), retry = useRef<{ signature: string; key: string } | null>(null), closeReport = useRef<(() => void) | null>(null)
  const scopeMatches = scope.actor === actor && scope.workspaceId === workspaceId
  const active = () => scopeMatches && life.current.active && life.current.scope === scope && !actor.signal?.aborted
  const manager = actor.role !== 'member', head = register?.versions.find(v => v.id === register.headVersionId), selected = register?.versions.find(v => v.id === selectedId), review = register?.reviews.find(r => r.versionId === selected?.id)
  const current = !selected || selected.id === head?.id, reconciliation = register?.reconciliation
  const canReview = manager && head && current && !editing && !review && !head.contributorIds.includes(actor.userId)
  const acceptanceBlocked = reconciliation?.findings.some(f => f.blocking && f.code !== 'roster_review_required') ?? true

  function accept(value: M75Register, preferred = '') { setRegister(value); setSelectedId(value.versions.some(v => v.id === preferred) ? preferred : value.headVersionId ?? ''); setEditing(false); setConfirmed(false); setReviewNote(''); setAck(false); setCurrentReportHash('') }
  useLayoutEffect(() => {
    const state = { scope, active: true }; life.current = state; lock.current = false; retry.current = null
    void (async () => { try { if (!scope.workspaceId) { setMessage('No company workspace is assigned.'); return } const value = await fleetRegisterRequest(scope.actor,scope.workspaceId); if (state.active && !scope.actor.signal?.aborted) { accept(value); setMessage('Declare the fleet, then inspect every missing or conflicting match.') } } catch (e) { if (state.active && !scope.actor.signal?.aborted) { setError(true); setMessage(e instanceof Error ? e.message : 'Fleet records unavailable.') } } finally { if (state.active && !scope.actor.signal?.aborted) setBusy(false) } })()
    return () => { state.active = false; closeReport.current?.(); closeReport.current = null }
  }, [scope])
  useEffect(() => {
    let live = true
    if (register && head) { const r = register.reviews.find(x => x.versionId === head.id) ?? null; void coverageSha256(m75CanonicalJson(m75ReportSnapshot(head,r,register.reconciliation))).then(value => { if (live) setCurrentReportHash(value) }).catch(() => { if (live) setCurrentReportHash('') }) }
    return () => { live = false }
  }, [register,head])
  if (!scopeMatches) { setScope({ actor,workspaceId }); setRegister(null); setSelectedId(''); setStatement(newFleetStatement()); setLinks([]); setEditing(false); setConfirmed(false); setReason(''); setBusy(true); setError(false); setMessage('Loading fleet records…'); setReviewNote(''); setAck(false); setDecision('changes_requested'); setCurrentReportHash('') }

  async function action(kind: string, payload: unknown, work: (key: string) => Promise<void>) {
    if (!active() || lock.current || !workspaceId) return
    lock.current = true; setBusy(true); setError(false)
    const signature = m75CanonicalJson({ kind, payload }); if (retry.current?.signature !== signature) retry.current = { signature,key:crypto.randomUUID() }
    try { await work(retry.current.key); if (active()) retry.current = null }
    catch (e) { if (active()) { setError(true); setMessage(e instanceof Error ? e.message : 'The action could not be verified. Retry the same action or refresh.') } }
    finally { if (active()) { lock.current = false; setBusy(false) } }
  }
  const refresh = () => action('refresh',null,async () => { const value = await fleetRegisterRequest(actor,workspaceId!); if (active()) { accept(value); setMessage('Fleet status refreshed against the current records.') } })
  function start() { if (!manager || busy || !active()) return; setStatement(structuredClone(head?.activity.rosterStatement ?? newFleetStatement())); setLinks(structuredClone(head?.activity.links ?? [])); setSelectedId(head?.id ?? ''); setConfirmed(false); setReason(''); setEditing(true); setError(false); setMessage('Unsaved roster. Enter its own evidence before matching corporate sources.') }
  async function save() {
    if (!manager || !register?.proof.coverageVersion || !reconciliation || !active()) return
