    try { validateM75Save({...input,idempotencyKey:crypto.randomUUID()}) } catch { setError(true); setMessage('Check the roster reference, evidence description, vehicle facts and correction reason. Unknown facts can remain blank; invalid dates or identifiers must be corrected. Nothing was saved.'); return }
    await action('save',input,async key => { await fleetSaveRequest(actor,workspaceId!,register.rosterId,{...input,idempotencyKey:key}); const fresh = await fleetRegisterRequest(actor,workspaceId!); if (active()) { accept(fresh); setMessage('Roster version saved. Inspect the findings and obtain a separate fleet review.') } })
