    await action('review',input,async key => { await fleetReviewRequest(actor,workspaceId!,register.rosterId!,{...input,idempotencyKey:key}); const fresh = await fleetRegisterRequest(actor,workspaceId!); if (active()) { accept(fresh); setMessage('Fleet review saved for the exact roster, boundary and workpaper versions.') } })
  }
  async function createReport() { if (!manager || !current || !register?.rosterId || !head || !reconciliation || editing) return; const input = { expectedReconciliationSha256:reconciliation.contentSha256 }; await action('report',input,async key => { await fleetReportRequest(actor,workspaceId!,register.rosterId!,{...input,idempotencyKey:key}); const fresh = await fleetRegisterRequest(actor,workspaceId!); if (active()) { accept(fresh); setMessage('Exact fleet report retained, including every open finding.') } }) }
  async function reportFile(report: M75ReportMetadata, mode: 'open' | 'download' | 'print' | 'snapshot') {
    await action('report-'+mode,report.id,async () => {
      if (mode === 'snapshot') { const text = await fleetReportSnapshotDownload(actor,workspaceId!,report); if (active()) { download(text,`fleet-report-${report.id}.json`,'application/json'); setMessage('Exact report snapshot downloaded.') } return }
      const html = await fleetReportDownload(actor,workspaceId!,report); if (!active()) return
      if (mode === 'download') { download(html,`fleet-report-${report.id}.html`,'text/html;charset=utf-8'); setMessage('Exact fleet report downloaded.'); return }
      closeReport.current?.(); const before = document.activeElement instanceof HTMLElement ? document.activeElement : null, dialog = document.createElement('dialog'), frame = document.createElement('iframe'), close = document.createElement('button')
      dialog.setAttribute('aria-label','Fleet reconciliation report'); dialog.style.cssText='width:90vw;max-width:1050px;height:90vh;padding:12px;background:white;color:#172f2c;border:2px solid #667085'
      frame.title='Fleet reconciliation report'; frame.setAttribute('sandbox','allow-same-origin allow-modals'); frame.style.cssText='display:block;width:100%;height:90%;border:0;background:white'; close.textContent='Close fleet report'; close.style.cssText='padding:10px 16px;margin-bottom:10px;font:inherit'
      const cleanup = () => { dialog.remove(); if (active()) before?.focus() }; closeReport.current=cleanup; close.onclick=() => { cleanup(); closeReport.current=null }; dialog.addEventListener('cancel',() => { cleanup(); closeReport.current=null })
      frame.onload=() => { if (mode === 'print' && active()) { try { frame.contentWindow?.print(); setMessage('Print preview requested for the exact fleet report.') } catch { setError(true); setMessage('Print preview could not open. Download the HTML report to print from your browser.') } } }; frame.srcdoc=html; dialog.append(close,frame); document.body.append(dialog); dialog.showModal(); close.focus()
    })
  }
  if (!scopeMatches) return <section className="worksheet"><h1 ref={headingRef} tabIndex={-1}>Fleet reconciliation</h1><p role="status">Loading fleet records…</p></section>
  return <section className="worksheet controlled-fleet">
    <p className="worksheet-eyebrow">California reporting · Private synthetic workspace</p><h1 ref={headingRef} tabIndex={-1}>Fleet reconciliation</h1>
    <p>Declare the whole fleet, then match every vehicle to its source and reviewed workpaper. Include all controlled trips, wherever they occur.</p>
    <div className="worksheet-context"><span>2025 calendar year</span><span>Declared fleet only</span><span>Scope 1 incomplete</span></div>
