    <div className="fleet-actions"><button type="button" disabled={busy} onClick={() => void refresh()}>Refresh fleet status</button><button type="button" disabled={busy} onClick={() => onNavigate('corporate')}>Open corporate register</button><button type="button" disabled={busy} onClick={() => onNavigate('mobile')}>Open vehicle workpapers</button>{manager && <button type="button" disabled={busy || !register?.proof.coverageVersion || editing} onClick={start}>{head ? 'Correct roster or refresh its links' : 'Declare fleet roster'}</button>}</div>
    {!register?.proof.coverageVersion && !busy && <p>Save the corporate boundary and source register before declaring the fleet.</p>}
