import {m75CanonicalJson} from './m75-validation'

const esc=(value:unknown)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!))
export const M75_REPORT_TEMPLATE=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Synthetic controlled-fleet reconciliation</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:1000px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;vertical-align:top;border-bottom:1px solid #ccd8d0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}.blocked{color:#8a281f}@media print{body{font-size:10pt;margin:0;max-width:none}h2{break-after:avoid}tr{break-inside:avoid}}</style></head><body><h1>Controlled-fleet reconciliation — synthetic internal draft</h1>{{summary}}<h2>Declared roster evidence</h2>{{evidence}}<h2>Full reconciliation union</h2>{{rows}}<h2>Open findings</h2>{{findings}}<h2>Limitations</h2>{{limitations}}<details><summary>Exact snapshot</summary><pre>{{snapshot}}</pre></details></body></html>`
export const m75ReportSnapshot=(version:M75Version,review:M75Review|null,reconciliation:M75Reconciliation)=>({profile:'m75-fleet-reconciliation-report-v1' as const,version,review,reconciliation})
export function m75RenderReport(snapshot:ReturnType<typeof m75ReportSnapshot>):string{
 const {version,review,reconciliation:r}=snapshot,statement=version.statement,blocked=r.status==='blocked'
 const summary=`<p class="${blocked?'blocked':''}"><strong>${esc(blocked?'Blocked — open findings remain':'Declared synthetic fleet reconciled to current internally reviewed workpapers')}</strong></p><p>Company ${esc(r.companyId)} · ${esc(r.period.start)} to ${esc(r.period.endExclusive)} · roster version ${version.version}. Fleet review: ${esc(review?.decision??'unreviewed')}.</p><p>No emissions aggregation. Candidate factors and methods are not released. Scope 1 and the corporate inventory remain incomplete. Requirements are not determined. No external assurance.</p>`
