create table neuvetra.controlled_fleet_heads(company_id uuid primary key references neuvetra.companies(id),id uuid not null,version_id uuid,revision integer not null default 0,unique(id,company_id));
create table neuvetra.controlled_fleet_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.controlled_fleet_versions(id uuid primary key,company_id uuid not null,roster_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,statement_id uuid,payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,roster_id,version),foreign key(roster_id,company_id) references neuvetra.controlled_fleet_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.controlled_fleet_versions(id,company_id),foreign key(coverage_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id),foreign key(statement_id,company_id) references neuvetra.controlled_fleet_statements(id,company_id));
alter table neuvetra.controlled_fleet_heads add constraint controlled_fleet_head_version_fk foreign key(version_id,company_id) references neuvetra.controlled_fleet_versions(id,company_id) deferrable initially deferred;
create table neuvetra.controlled_fleet_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.controlled_fleet_versions(id,company_id));
create table neuvetra.controlled_fleet_reports(id uuid primary key,company_id uuid not null,roster_id uuid not null,version_id uuid not null,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(roster_id,company_id) references neuvetra.controlled_fleet_heads(id,company_id),foreign key(version_id,company_id) references neuvetra.controlled_fleet_versions(id,company_id));
create table neuvetra.controlled_fleet_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
