do $$declare t text;begin foreach t in array array['controlled_fleet_heads','controlled_fleet_statements','controlled_fleet_versions','controlled_fleet_reviews','controlled_fleet_reports','controlled_fleet_requests','controlled_fleet_audit'] loop execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m75_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);if t<>'controlled_fleet_heads' then execute format('create trigger m75_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;

create function neuvetra.m75_lock(target_company uuid,writing boolean) returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing) then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.controlled_fleet_heads where company_id=target_company for update;perform id from neuvetra.mobile_diesel_heads where company_id=target_company order by id for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;

create function neuvetra.m75_exact_keys(value jsonb, expected text[]) returns boolean language sql immutable set search_path=pg_catalog as $$select jsonb_typeof(value)='object' and (select coalesce(array_agg(k order by k),'{}'::text[]) from jsonb_object_keys(value) k)=(select coalesce(array_agg(k order by k),'{}'::text[]) from unnest(expected) k)$$;

create function neuvetra.m75_text_valid(value jsonb,max_chars integer) returns boolean language sql immutable set search_path=pg_catalog as $$select jsonb_typeof(value)='string' and length(btrim(value#>>'{}')) between 1 and max_chars and value#>>'{}'=btrim(value#>>'{}') and normalize(value#>>'{}',NFC)=value#>>'{}' and value#>>'{}'!~'[\u0000-\u001F\u007F-\u009F]'$$;

create function neuvetra.m75_activity_valid(activity jsonb) returns boolean language plpgsql immutable set search_path=pg_catalog,neuvetra as $$declare s jsonb;a jsonb;l jsonb;p jsonb;begin if not neuvetra.m75_exact_keys(activity,array['profile','coverageVersionId','coverageVersionSha256','period','rosterStatement','manualConfirmation','links']) or activity->>'profile' is distinct from 'synthetic-controlled-fleet-v1' or activity->>'coverageVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or activity->>'coverageVersionSha256'!~'^[0-9a-f]{64}$' or activity->'period' is distinct from jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01') or jsonb_typeof(activity->'manualConfirmation') is distinct from 'boolean' or jsonb_typeof(activity->'links') is distinct from 'array' or jsonb_array_length(activity->'links')>25 then return false;end if;s:=activity->'rosterStatement';if s='null'::jsonb then return activity->'links'='[]'::jsonb;end if;if not neuvetra.m75_exact_keys(s,array['issuer','reference','description','discoveryBasis','coveredEntityIds','completeness','allTripLocationsIncluded','assets']) or not neuvetra.m75_text_valid(s->'issuer',120) or not neuvetra.m75_text_valid(s->'reference',120) or not neuvetra.m75_text_valid(s->'description',2000) or not neuvetra.m75_text_valid(s->'discoveryBasis',2000) or jsonb_typeof(s->'coveredEntityIds') is distinct from 'array' or s->>'completeness' not in('declared_complete','partial','unknown') or jsonb_typeof(s->'allTripLocationsIncluded') is distinct from 'boolean' or jsonb_typeof(s->'assets') is distinct from 'array' or jsonb_array_length(s->'assets')>25 then return false;end if;if exists(select 1 from jsonb_array_elements(s->'coveredEntityIds') x where jsonb_typeof(x)<>'string' or x#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') or s->'coveredEntityIds' is distinct from (select coalesce(jsonb_agg(x order by x#>>'{}' collate "C"),'[]'::jsonb) from(select distinct x from jsonb_array_elements(s->'coveredEntityIds') x) q) then return false;end if;for a in select x from jsonb_array_elements(s->'assets') x loop if not neuvetra.m75_exact_keys(a,array['rowId','assetId','aliases','entityId','facilityId','period','mode','vehicleClass','modelYear','fuel','controlBasis','classificationBasis','controlExplanation']) or a->>'rowId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or (a->'assetId'<>'null'::jsonb and (jsonb_typeof(a->'assetId')<>'string' or a->>'assetId'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$')) or jsonb_typeof(a->'aliases') is distinct from 'array' or jsonb_array_length(a->'aliases')>8 or exists(select 1 from jsonb_array_elements(a->'aliases') x where jsonb_typeof(x)<>'string' or x#>>'{}'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$') or a->'aliases' is distinct from (select coalesce(jsonb_agg(x order by x#>>'{}' collate "C"),'[]'::jsonb) from(select distinct x from jsonb_array_elements(a->'aliases') x) q) or (a->'assetId'<>'null'::jsonb and (a->'aliases') ? (a->>'assetId')) or (a->'entityId'<>'null'::jsonb and (jsonb_typeof(a->'entityId')<>'string' or a->>'entityId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) or (a->'facilityId'<>'null'::jsonb and (jsonb_typeof(a->'facilityId')<>'string' or a->>'facilityId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) or (a->'period'<>'null'::jsonb and (not neuvetra.m75_exact_keys(a->'period',array['start','endExclusive']) or a#>>'{period,start}'!~'^\d{4}-\d{2}-\d{2}$' or a#>>'{period,endExclusive}'!~'^\d{4}-\d{2}-\d{2}$' or to_char(to_date(a#>>'{period,start}','FXYYYY-MM-DD'),'YYYY-MM-DD')<>a#>>'{period,start}' or to_char(to_date(a#>>'{period,endExclusive}','FXYYYY-MM-DD'),'YYYY-MM-DD')<>a#>>'{period,endExclusive}' or a#>>'{period,start}'>=a#>>'{period,endExclusive}')) or a->>'mode' not in('on_road','off_road','rail','marine','air','other','unknown') or (a->'vehicleClass'<>'null'::jsonb and not neuvetra.m75_text_valid(a->'vehicleClass',100)) or (a->'modelYear'<>'null'::jsonb and (jsonb_typeof(a->'modelYear')<>'number' or a->>'modelYear'!~'^\d{4}$' or (a->>'modelYear')::integer not between 1900 and 2100)) or (a->'fuel'<>'null'::jsonb and not neuvetra.m75_text_valid(a->'fuel',100)) or a->>'controlBasis' not in('owned_operational_control_full_year','other_control_arrangement','unknown') or (a->'classificationBasis'<>'null'::jsonb and not neuvetra.m75_text_valid(a->'classificationBasis',500)) or (a->'controlExplanation'<>'null'::jsonb and not neuvetra.m75_text_valid(a->'controlExplanation',500)) then return false;end if;end loop;if (select count(*) from jsonb_array_elements(s->'assets'))<>(select count(distinct x->>'rowId') from jsonb_array_elements(s->'assets') x) then return false;end if;for l in select x from jsonb_array_elements(activity->'links') x loop if not neuvetra.m75_exact_keys(l,array['rowId','sourceId']) or l->>'rowId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or (l->'sourceId'<>'null'::jsonb and (jsonb_typeof(l->'sourceId')<>'string' or l->>'sourceId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) then return false;end if;end loop;return (select count(*) from jsonb_array_elements(activity->'links'))=(select count(distinct x->>'rowId') from jsonb_array_elements(activity->'links') x) and (select jsonb_agg(to_jsonb(x->>'rowId') order by x->>'rowId' collate "C") from jsonb_array_elements(activity->'links') x)=(select jsonb_agg(to_jsonb(x->>'rowId') order by x->>'rowId' collate "C") from jsonb_array_elements(s->'assets') x);exception when others then return false;end $$;

create function neuvetra.m75_current_dependencies(target_company uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$with coverage as(select v.id,v.version_sha256,r.id review_id,r.decision_sha256 from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on(v.company_id=h.company_id and v.id=h.version_id) left join neuvetra.corporate_inventory_reviews r on(r.company_id=v.company_id and r.version_id=v.id) where h.company_id=target_company),pins as(select coalesce(jsonb_agg(jsonb_build_object('worksheetId',v.worksheet_id,'sourceId',v.payload#>'{activity,binding,sourceId}','assetId',v.payload#>'{activity,vehicle,assetId}','version',jsonb_build_object('id',v.id,'sha256',v.version_sha256),'decision',case when r.id is null then 'null'::jsonb else jsonb_build_object('id',r.id,'sha256',r.decision_sha256)end) order by v.worksheet_id),'[]'::jsonb) value from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on(v.company_id=h.company_id and v.id=h.version_id) left join neuvetra.mobile_diesel_reviews r on(r.company_id=v.company_id and r.version_id=v.id) where h.company_id=target_company),body as(select jsonb_build_object('coveragePin',case when c.id is null then 'null'::jsonb else jsonb_build_object('id',c.id,'sha256',c.version_sha256)end,'coverageReviewPin',case when c.review_id is null then 'null'::jsonb else jsonb_build_object('id',c.review_id,'sha256',c.decision_sha256)end,'workpaperPins',p.value) value from pins p left join coverage c on true) select value||jsonb_build_object('dependencySha256',neuvetra.m67_hash(value)) from body$$;

create function neuvetra.m75_local_blocked(target_company uuid,activity jsonb) returns boolean language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$with cv as(select v.payload from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company),assets as(select a from jsonb_array_elements(coalesce(activity#>'{rosterStatement,assets}','[]'::jsonb)) a),links as(select l from jsonb_array_elements(activity->'links') l),identities as(select a->>'assetId' id from assets where a->>'assetId' is not null union all select alias#>>'{}' from assets cross join lateral jsonb_array_elements(a->'aliases') alias) select activity->'rosterStatement'='null'::jsonb or activity->>'manualConfirmation'<>'true' or jsonb_array_length(coalesce(activity#>'{rosterStatement,assets}','[]'::jsonb))=0 or activity#>>'{rosterStatement,completeness}'<>'declared_complete' or activity#>>'{rosterStatement,allTripLocationsIncluded}'<>'true' or activity#>'{rosterStatement,coveredEntityIds}' is distinct from (select jsonb_agg(to_jsonb(e->>'id') order by e->>'id') from cv,jsonb_array_elements(cv.payload#>'{snapshot,entities}') e) or exists(select 1 from assets a where a.a->>'assetId' is null or a.a->>'entityId' is null or a.a->>'facilityId' is null or a.a->'period'='null'::jsonb or a.a->>'mode'='unknown' or a.a->>'vehicleClass' is null or a.a->>'modelYear' is null or a.a->>'fuel' is null or a.a->>'controlBasis'='unknown' or a.a->>'classificationBasis' is null or a.a->>'controlExplanation' is null or not exists(select 1 from cv,jsonb_array_elements(cv.payload#>'{snapshot,entities}') e where e->>'id'=a.a->>'entityId') or not exists(select 1 from cv,jsonb_array_elements(cv.payload#>'{snapshot,facilities}') f where f->>'id'=a.a->>'facilityId' and f->>'entityId'=a.a->>'entityId') or not exists(select 1 from links l,cv,jsonb_array_elements(cv.payload#>'{snapshot,sources}') s where l.l->>'rowId'=a.a->>'rowId' and l.l->>'sourceId'=s->>'id' and s->>'domain'='mobile_combustion') or a.a->>'mode'<>'on_road' or a.a->>'vehicleClass'<>'Medium- and Heavy-Duty Vehicles' or (a.a->>'modelYear')::integer not between 2007 and 2022 or a.a->>'fuel'<>'Fossil Diesel' or a.a->>'controlBasis'<>'owned_operational_control_full_year' or a.a#>>'{period,start}'<>'2025-01-01' or a.a#>>'{period,endExclusive}'<>'2026-01-01') or exists(select 1 from identities group by id having count(*)>1) or exists(select 1 from links where l->>'sourceId' is not null group by l->>'sourceId' having count(*)>1)$$;

-- Root-authored fragment for backend integration. Exact TS roster-local findings.
-- Inputs must pass the save contract before this function is called.
create function neuvetra.m75_roster_findings(activity jsonb, coverage jsonb)
returns jsonb language plpgsql immutable set search_path=pg_catalog as $$
declare
 out_findings jsonb := '[]'::jsonb;
 statement jsonb := activity->'rosterStatement';
 asset jsonb;
 row_key text;
 source_id text;
 expected_entities jsonb;
 supported boolean;
 identity_row record;
begin

if statement is null or statement='null'::jsonb then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_statement_missing','rowKey',null,'message','The declared controlled-vehicle roster statement is missing.','blocking',true)); return out_findings; end if;
if activity->>'manualConfirmation' is distinct from 'true' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_unconfirmed','rowKey',null,'message','Confirm the complete synthetic roster declaration.','blocking',true)); end if;
if jsonb_array_length(statement->'assets')=0 then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_empty','rowKey',null,'message','An empty roster cannot establish a zero fleet.','blocking',true)); end if;
if statement->>'completeness' is distinct from 'declared_complete' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_not_declared_complete','rowKey',null,'message','The roster population is partial or unknown.','blocking',true)); end if;
if statement->>'allTripLocationsIncluded' is distinct from 'true' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','trip_locations_incomplete','rowKey',null,'message','The roster declaration must cover all trip locations, including interstate travel.','blocking',true)); end if;
select coalesce(jsonb_agg(to_jsonb(e->>'id') order by (e->>'id') collate "C"),'[]'::jsonb) into expected_entities from jsonb_array_elements(coverage#>'{snapshot,entities}') e;
if statement->'coveredEntityIds' is distinct from expected_entities then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','entity_population_incomplete','rowKey',null,'message','Every entity in the bound corporate register needs a roster population declaration.','blocking',true)); end if;
for asset in select a from jsonb_array_elements(statement->'assets') with ordinality x(a,n) order by n loop
 row_key := 'roster:'||(asset->>'rowId');
 select l->>'sourceId' into source_id from jsonb_array_elements(activity->'links') with ordinality x(l,n) where l->>'rowId'=asset->>'rowId' order by n desc limit 1;
 if nullif(asset->>'entityId','') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=asset->>'entityId') then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','unknown_entity','rowKey',row_key,'message','The declared entity is not in the bound corporate register.','blocking',true)); end if;
 if nullif(asset->>'facilityId','') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=asset->>'facilityId' and (nullif(asset->>'entityId','') is null or f->>'entityId'=asset->>'entityId')) then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','facility_conflict','rowKey',row_key,'message','The declared facility is missing or belongs to another entity.','blocking',true)); end if;
 if nullif(source_id,'') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,sources}') s where s->>'id'=source_id and s->>'domain'='mobile_combustion') then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','source_conflict','rowKey',row_key,'message','The mapped source is missing or is not mobile combustion.','blocking',true)); end if;
 if nullif(asset->>'assetId','') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','asset_identity_unknown','rowKey',row_key,'message','Stable vehicle identity is unknown.','blocking',true)); end if;
 if nullif(asset->>'entityId','') is null or nullif(asset->>'facilityId','') is null or coalesce(asset->'period','null'::jsonb)='null'::jsonb or asset->>'mode'='unknown' or nullif(asset->>'vehicleClass','') is null or asset->>'modelYear' is null or nullif(asset->>'fuel','') is null or asset->>'controlBasis'='unknown' or nullif(asset->>'classificationBasis','') is null or nullif(asset->>'controlExplanation','') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','vehicle_facts_unknown','rowKey',row_key,'message','One or more required vehicle, period, classification or control facts are unknown.','blocking',true)); end if;
 supported := coalesce(asset->>'mode'='on_road' and asset->>'vehicleClass'='Medium- and Heavy-Duty Vehicles' and (asset->>'modelYear')::integer between 2007 and 2022 and asset->>'fuel'='Fossil Diesel' and asset->>'controlBasis'='owned_operational_control_full_year' and asset->'period'=jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01'),false);
 if not supported and nullif(asset->>'assetId','') is not null and asset->>'mode'<>'unknown' and nullif(asset->>'vehicleClass','') is not null and asset->>'modelYear' is not null and nullif(asset->>'fuel','') is not null and asset->>'controlBasis'<>'unknown' and coalesce(asset->'period','null'::jsonb)<>'null'::jsonb then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','vehicle_profile_unsupported','rowKey',row_key,'message','The controlled vehicle is outside the current M74 candidate profile.','blocking',true)); end if;
 if nullif(source_id,'') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','source_missing','rowKey',row_key,'message','No current corporate mobile source is mapped to this roster row.','blocking',true)); end if;
end loop;
-- Match JavaScript Map insertion order: first occurrence of each identity,
-- then every occurrence's original asset/alias order (including duplicates).
for identity_row in
 with assets as(select a,n from jsonb_array_elements(statement->'assets') with ordinality x(a,n)),
 identities as(
  select a->>'assetId' identity,a->>'rowId' row_id,n asset_order,0::bigint alias_order from assets where nullif(a->>'assetId','') is not null
  union all select alias#>>'{}',a->>'rowId',n,k from assets cross join lateral jsonb_array_elements(a->'aliases') with ordinality x(alias,k)
 ), positions as(select *,row_number() over(order by asset_order,alias_order) position from identities),
 repeated as(select *,count(*) over(partition by identity) occurrences,min(position) over(partition by identity) first_position from positions)
 select identity,row_id from repeated where occurrences>1 order by first_position,position
loop

 out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','duplicate_asset_identity','rowKey','roster:'||identity_row.row_id,'message','Declared asset identity '||identity_row.identity||' appears in multiple roster rows.','blocking',true));
end loop;
for identity_row in
 with assets as(select a,n from jsonb_array_elements(statement->'assets') with ordinality x(a,n)),
 mapped as(select a->>'rowId' row_id,n,(select l->>'sourceId' from jsonb_array_elements(activity->'links') with ordinality x(l,k) where l->>'rowId'=a->>'rowId' order by k desc limit 1) identity from assets),
 repeated as(select *,count(*) over(partition by identity) occurrences,min(n) over(partition by identity) first_position from mapped where nullif(identity,'') is not null)
 select identity,row_id from repeated where occurrences>1 order by first_position,n
loop

 out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','duplicate_source_mapping','rowKey','roster:'||identity_row.row_id,'message','Corporate mobile source '||identity_row.identity||' is mapped to multiple roster rows.','blocking',true));
end loop;
return out_findings;
end $$;

create function neuvetra.m75_acceptance_ready(target_company uuid,version_payload jsonb) returns boolean language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$with cv as(select v.payload from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id join neuvetra.corporate_inventory_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company and r.payload->>'decision'='accepted_bounded_internal'),assets as(select a from jsonb_array_elements(version_payload#>'{activity,rosterStatement,assets}') a),links as(select l from jsonb_array_elements(version_payload#>'{activity,links}') l),sources as(select s from cv,jsonb_array_elements(cv.payload#>'{snapshot,sources}') s where s->>'domain'='mobile_combustion'),wps as(select v.payload p,r.payload review from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id join neuvetra.mobile_diesel_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company) select exists(select 1 from cv) and version_payload->'findings'='[]'::jsonb and version_payload#>>'{activity,manualConfirmation}'='true' and version_payload#>>'{activity,rosterStatement,completeness}'='declared_complete' and version_payload#>>'{activity,rosterStatement,allTripLocationsIncluded}'='true' and (select count(*) from assets)=(select count(*) from links) and (select count(*) from assets)=(select count(*) from sources) and (select count(*) from assets)=(select count(*) from wps) and not exists(select 1 from sources s where not exists(select 1 from cv,jsonb_array_elements(cv.payload#>'{snapshot,coverageItems}') i where i->>'sourceId'=s.s->>'id' and i->>'disposition'='included_activity')) and version_payload#>'{activity,rosterStatement,coveredEntityIds}'=(select jsonb_agg(to_jsonb(e->>'id') order by e->>'id') from cv,jsonb_array_elements(cv.payload#>'{snapshot,entities}') e) and not exists(select 1 from assets a where a.a->>'mode'<>'on_road' or a.a->>'vehicleClass'<>'Medium- and Heavy-Duty Vehicles' or (a.a->>'modelYear')::integer not between 2007 and 2022 or a.a->>'fuel'<>'Fossil Diesel' or a.a->>'controlBasis'<>'owned_operational_control_full_year' or a.a#>>'{period,start}'<>'2025-01-01' or a.a#>>'{period,endExclusive}'<>'2026-01-01') and not exists(select 1 from(select id,count(*) n from(select a->>'assetId' id from assets where a->>'assetId' is not null union all select alias#>>'{}' from assets cross join lateral jsonb_array_elements(a->'aliases') alias) identities group by id having count(*)>1) d) and not exists(select 1 from links group by l->>'sourceId' having count(*)>1) and not exists(select 1 from links l where not exists(select 1 from assets a where a.a->>'rowId'=l.l->>'rowId') or not exists(select 1 from sources s where s.s->>'id'=l.l->>'sourceId') or not exists(select 1 from wps w,assets a where a.a->>'rowId'=l.l->>'rowId' and w.p#>>'{activity,binding,sourceId}'=l.l->>'sourceId' and (w.p#>>'{activity,vehicle,assetId}'=a.a->>'assetId' or (a.a->'aliases') ? (w.p#>>'{activity,vehicle,assetId}')) and w.p#>>'{activity,binding,entityId}'=a.a->>'entityId' and w.p#>>'{activity,binding,facilityId}'=a.a->>'facilityId' and w.p#>>'{activity,vehicle,vehicleClass}'=a.a->>'vehicleClass' and w.p#>>'{activity,vehicle,modelYear}'=a.a->>'modelYear' and w.p#>>'{activity,vehicle,fuel}'=a.a->>'fuel' and w.p#>>'{activity,vehicle,controlBasis}'=a.a->>'controlBasis' and w.p->'calculation'<>'null'::jsonb and w.p#>>'{activityStatus,fuel}' in('entered','explicit_zero') and w.p#>>'{activityStatus,mileage}' in('entered','explicit_zero') and w.p#>>'{activity,binding,coverageVersionId}'=(neuvetra.m75_current_dependencies(target_company)#>>'{coveragePin,id}') and w.p#>>'{activity,binding,coverageVersionSha256}'=(neuvetra.m75_current_dependencies(target_company)#>>'{coveragePin,sha256}') and w.review->>'decision'='accepted_bounded_internal' and not exists(select 1 from jsonb_array_elements(w.p->'findings') f where f->>'code' not in('scope1_incomplete','method_not_released'))))$$;

create function neuvetra.m75_html_escape(value text) returns text language sql immutable set search_path=pg_catalog as $$select replace(replace(replace(replace(replace(coalesce(value,''),'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),'''','&#39;')$$;

create function neuvetra.m75_render_report(snapshot jsonb) returns text language sql immutable set search_path=pg_catalog,neuvetra as $$with r as(select snapshot->'version' v,snapshot->'review' review,snapshot->'reconciliation' reconciliation),parts as(select '<p class="'||case when reconciliation->>'status'='blocked' then 'blocked' else '' end||'"><strong>'||neuvetra.m75_html_escape(case when reconciliation->>'status'='blocked' then 'Blocked — open findings remain' else 'Declared synthetic fleet reconciled to current internally reviewed workpapers' end)||'</strong></p><p>Company '||neuvetra.m75_html_escape(reconciliation->>'companyId')||' · '||neuvetra.m75_html_escape(reconciliation#>>'{period,start}')||' to '||neuvetra.m75_html_escape(reconciliation#>>'{period,endExclusive}')||' · roster version '||neuvetra.m75_html_escape(v->>'version')||'. Fleet review: '||neuvetra.m75_html_escape(coalesce(review->>'decision','unreviewed'))||'.</p><p>No emissions aggregation. Candidate factors and methods are not released. Scope 1 and the corporate inventory remain incomplete. Requirements are not determined. No external assurance.</p>' summary,case when v->'statement'='null'::jsonb then '<p class="blocked">Roster statement missing.</p>' else '<dl><dt>Locator</dt><dd>'||neuvetra.m75_html_escape(v#>>'{statement,locator}')||'</dd><dt>SHA-256</dt><dd>'||neuvetra.m75_html_escape(v#>>'{statement,sha256}')||'</dd><dt>Issuer / reference</dt><dd>'||neuvetra.m75_html_escape(v#>>'{statement,input,issuer}')||' / '||neuvetra.m75_html_escape(v#>>'{statement,input,reference}')||'</dd><dt>Declaration</dt><dd>'||neuvetra.m75_html_escape(v#>>'{statement,input,completeness}')||' · all trip locations '||case when v#>>'{statement,input,allTripLocationsIncluded}'='true' then 'included' else 'not confirmed' end||'</dd></dl>' end evidence,coalesce((select string_agg('<tr><td>'||neuvetra.m75_html_escape(coalesce(x->>'rosterRowId','—'))||'</td><td>'||neuvetra.m75_html_escape(coalesce(x->>'assetId','unknown'))||'</td><td>'||neuvetra.m75_html_escape(coalesce(x->>'sourceId','—'))||'<br>'||coalesce((select string_agg(neuvetra.m75_html_escape(w#>>'{}'),'<br>' order by n) from jsonb_array_elements(x->'worksheetIds') with ordinality q(w,n)),'—')||'</td><td>'||neuvetra.m75_html_escape(x->>'status')||'</td><td>'||coalesce((select string_agg(neuvetra.m75_html_escape(f->>'message'),'<br>' order by n) from jsonb_array_elements(x->'findings') with ordinality q(f,n)),'—')||'</td></tr>','' order by n) from jsonb_array_elements(reconciliation->'rows') with ordinality q(x,n)),'') rows,case when jsonb_array_length(reconciliation->'findings')=0 then '<p>No reconciliation blockers.</p>' else '<ul>'||(select string_agg('<li>'||neuvetra.m75_html_escape(f->>'code')||': '||neuvetra.m75_html_escape(f->>'message')||'</li>','' order by n) from jsonb_array_elements(reconciliation->'findings') with ordinality q(f,n))||'</ul>' end findings,'<ul>'||(select string_agg('<li>'||neuvetra.m75_html_escape(x#>>'{}')||'</li>','' order by n) from jsonb_array_elements(reconciliation->'limitations') with ordinality q(x,n))||'</ul>' limitations from r) select '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic controlled-fleet reconciliation</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:1000px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;vertical-align:top;border-bottom:1px solid #ccd8d0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}.blocked{color:#8a281f}@media print{body{font-size:10pt;margin:0;max-width:none}h2{break-after:avoid}tr{break-inside:avoid}}</style></head><body><h1>Controlled-fleet reconciliation — synthetic internal draft</h1>'||summary||'<h2>Declared roster evidence</h2>'||evidence||'<h2>Full reconciliation union</h2><table><thead><tr><th>Roster row</th><th>Asset</th><th>Source / workpaper</th><th>Status</th><th>Findings</th></tr></thead><tbody>'||rows||'</tbody></table><h2>Open findings</h2>'||findings||'<h2>Limitations</h2>'||limitations||'<details><summary>Exact snapshot</summary><pre>'||neuvetra.m75_html_escape(neuvetra.m67_canonical(snapshot))||'</pre></details></body></html>' from parts$$;

create function neuvetra.m75_reconciliation_shape_valid(target_company uuid,snapshot jsonb) returns boolean language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$with rec as(select snapshot->'reconciliation' r,snapshot->'version' v,snapshot->'review' review),deps as(select neuvetra.m75_current_dependencies(target_company) d),sources as(select s from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.company_id=h.company_id and v.id=h.version_id,jsonb_array_elements(v.payload#>'{snapshot,sources}') s where h.company_id=target_company and s->>'domain'='mobile_combustion'),wps as(select h.id worksheet_id,v.payload p from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on v.company_id=h.company_id and v.id=h.version_id where h.company_id=target_company),links as(select l from rec,jsonb_array_elements(rec.v#>'{activity,links}') l),expected_keys as(select 'roster:'||(a->>'rowId') k from rec,jsonb_array_elements(rec.v#>'{activity,rosterStatement,assets}') a union all select 'source:'||(s->>'id') from sources where not exists(select 1 from links where l->>'sourceId'=s->>'id') union all select 'workpaper:'||worksheet_id::text from wps where not exists(select 1 from links where l->>'sourceId'=p#>>'{activity,binding,sourceId}') and not exists(select 1 from sources where s->>'id'=p#>>'{activity,binding,sourceId}')) select neuvetra.m75_exact_keys(r,array['profile','companyId','period','rosterPin','rosterReviewPin','coveragePin','coverageReviewPin','workpaperPins','rows','findings','counts','status','dependencySha256','limitations','synthetic','scope1Completeness','corporateCompleteness','releaseEligible','assurance','emissionsTotals','contentSha256']) and r->>'profile'='m75-fleet-reconciliation-v1' and r->>'companyId'=target_company::text and r->'period'=jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01') and r->'rosterPin'=jsonb_build_object('id',v->'id','sha256',v->'versionSha256') and r->'rosterReviewPin' is not distinct from case when review='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',review->'id','sha256',review->'decisionSha256') end and r->'coveragePin'=d#>'{coveragePin}' and r->'coverageReviewPin'=d#>'{coverageReviewPin}' and r->'workpaperPins'=d->'workpaperPins' and r->>'dependencySha256'=d->>'dependencySha256' and r->>'synthetic'='true' and r->>'scope1Completeness'='incomplete' and r->>'corporateCompleteness'='incomplete' and r->>'releaseEligible'='false' and r->>'assurance'='none' and r->'emissionsTotals'='null'::jsonb and r->'limitations'='["synthetic_only","declared_roster_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb and r#>>'{counts,evidenceRows}'=(jsonb_array_length(coalesce(v#>'{activity,rosterStatement,assets}','[]'::jsonb)))::text and r#>>'{counts,declaredUniqueKnownAssets}'=(select count(distinct a->>'assetId')::text from jsonb_array_elements(coalesce(v#>'{activity,rosterStatement,assets}','[]'::jsonb)) a where a->>'assetId' is not null) and r#>>'{counts,currentMobileSources}'=(select count(*)::text from sources) and r#>>'{counts,currentWorkpaperStreams}'=(select count(*)::text from wps) and r#>>'{counts,reconciledRows}'=(select count(*)::text from jsonb_array_elements(r->'rows') x where x->>'status'='matched_reviewed') and r#>>'{counts,blockingFindings}'=(select count(*)::text from jsonb_array_elements(r->'findings') f where f->>'blocking'='true') and (select jsonb_agg(to_jsonb(x->>'rowKey') order by (x->>'rowKey') collate "C") from jsonb_array_elements(r->'rows') x)=(select jsonb_agg(to_jsonb(k) order by k collate "C") from expected_keys) and not exists(select 1 from jsonb_array_elements(r->'rows') x where not neuvetra.m75_exact_keys(x,array['rowKey','rosterRowId','sourceId','assetId','worksheetIds','entityLabel','facilityLabel','sourceLabel','status','findings'])) and not exists(select 1 from jsonb_array_elements(r->'findings') f where not neuvetra.m75_exact_keys(f,array['code','rowKey','message','blocking']) or f->>'blocking'<>'true') and r->>'contentSha256'=neuvetra.m67_hash(r-'contentSha256') from rec,deps$$;

-- Exact current reconciliation derivation. Root authored; independent review required.
create function neuvetra.m75_source_eligible(coverage jsonb, source jsonb) returns boolean
language plpgsql immutable set search_path=pg_catalog as $$
declare entity jsonb; facility jsonb; boundary jsonb; relationship jsonb; current_id text; seen text[]:='{}'; item jsonb;
begin
select e into entity from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=source->>'entityId' limit 1;
select f into facility from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=source->>'facilityId' limit 1;
select b into boundary from jsonb_array_elements(coverage#>'{snapshot,boundaryDecisions}') with ordinality x(b,n) where b->>'entityId'=source->>'entityId' and b->>'start'='2025-01-01' and b->>'endExclusive'='2026-01-01' order by n limit 1;
if coverage#>>'{snapshot,consolidationApproach}' is distinct from 'operational_control' or entity is null or facility is null or facility->>'entityId' is distinct from entity->>'id' or entity->>'countryCode' is distinct from 'US' or entity->>'regionCode' is distinct from 'CA' or facility->>'countryCode' is distinct from 'US' or facility->>'regionCode' is distinct from 'CA' then return false; end if;
foreach item in array array[coverage#>'{snapshot,period}',entity,facility,source] loop
 if item->>'start' is distinct from '2025-01-01' or item->>'endExclusive' is distinct from '2026-01-01' then return false; end if;
end loop;

if boundary is null or boundary->>'disposition' is distinct from 'included_activity' or nullif(btrim(boundary->>'reason'),'') is null or not exists(select 1 from jsonb_array_elements(boundary->'evidenceRefs') r where r->>'artifactId'='71000000-0000-4000-8000-000000000900' and r->>'expectedSha256'='4fe7dc12d8f253f8d3cb1fd7fba2eade05f3d605ad7cb95376cca9d957afe5c7' and r->>'locator'='synthetic-register:entities-and-screening') then return false;end if;
current_id:=entity->>'id';while current_id is not null and current_id<>'' loop
 if current_id=any(seen) then return false;end if;seen:=array_append(seen,current_id);
 select r into relationship from jsonb_array_elements(coverage#>'{snapshot,relationships}') with ordinality x(r,n) where r->>'childEntityId'=current_id order by n limit 1;
 if relationship is null then exit;end if;
if relationship->>'start' is distinct from '2025-01-01' or relationship->>'endExclusive' is distinct from '2026-01-01' or relationship->>'ownershipPercent' is distinct from '100' or nullif(btrim(relationship->>'controlFacts'),'') is null or not exists(select 1 from jsonb_array_elements(relationship->'evidenceRefs') r where r->>'artifactId'='71000000-0000-4000-8000-000000000900' and r->>'expectedSha256'='4fe7dc12d8f253f8d3cb1fd7fba2eade05f3d605ad7cb95376cca9d957afe5c7' and r->>'locator'='synthetic-register:entities-and-screening') then return false;end if;
 current_id:=relationship->>'parentEntityId';
end loop;return true;end $$;
create function neuvetra.m75_row_status(findings jsonb) returns text language plpgsql immutable set search_path=pg_catalog as $$
declare codes text[]; code text;
begin select coalesce(array_agg(f->>'code'),'{}') into codes from jsonb_array_elements(findings) f where f->>'blocking'='true';
if exists(select 1 from unnest(codes) c where left(c,10)='duplicate_') then return 'duplicate';end if;
if 'vehicle_profile_unsupported'=any(codes) then return 'unsupported';end if;
if exists(select 1 from unnest(codes) c where position('unknown' in c)>0 or position('unconfirmed' in c)>0) then return 'unknown';end if;
if 'orphan_source'=any(codes) then return 'orphan_source';end if;
if 'orphan_workpaper'=any(codes) then return 'orphan_workpaper';end if;
if 'source_missing'=any(codes) then return 'missing_source';end if;
if exists(select 1 from unnest(codes) c where position('stale' in c)>0) then return 'stale';end if;
if 'capacity_blocked'=any(codes) then return 'capacity_blocked';end if;
if 'workpaper_missing'=any(codes) then return 'missing_workpaper';end if;
if cardinality(codes)>0 then return 'workpaper_incomplete';end if;
return 'matched_reviewed';end $$;

create function neuvetra.m75_derive_reconciliation(target_company uuid,coverage jsonb,workpapers jsonb,version_payload jsonb,reviews jsonb)
returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra as $$
declare
 deps jsonb; pins jsonb; global_findings jsonb:='[]'; rows_json jsonb:='[]'; all_findings jsonb;
 activity jsonb:=version_payload->'activity'; statement jsonb:=activity->'rosterStatement';
 sources jsonb; source jsonb; asset jsonb; head jsonb; works jsonb; findings jsonb; screening jsonb;
 row_key text; source_id text; worksheet_ids jsonb; mapped_sources text[]:='{}'; used_worksheets text[]:='{}';
 entity_label text; facility_label text; current_review jsonb; final_status text; base jsonb;
begin
select coalesce(jsonb_agg(jsonb_build_object('worksheetId',w->'worksheetId','sourceId',w#>'{activity,binding,sourceId}','assetId',w#>'{activity,vehicle,assetId}','version',jsonb_build_object('id',w->'id','sha256',w->'versionSha256'),'decision',case when coalesce(w->'review','null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',w#>'{review,id}','sha256',w#>'{review,decisionSha256}') end) order by (w->>'worksheetId') collate "C"),'[]'::jsonb) into pins from jsonb_array_elements(workpapers) w;
deps:=jsonb_build_object('coveragePin',case when coalesce(coverage,'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',coverage->'id','sha256',coverage->'versionSha256') end,'coverageReviewPin',case when coalesce(coverage->'review','null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',coverage#>'{review,id}','sha256',coverage#>'{review,decisionSha256}') end,'workpaperPins',pins);
deps:=deps||jsonb_build_object('dependencySha256',neuvetra.m67_hash(deps));

if coverage#>>'{review,decision}' is distinct from 'accepted_bounded_internal' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','coverage_review_required','rowKey',null,'message','The exact current corporate coverage version needs bounded internal acceptance.','blocking',true)); end if;
if coalesce(version_payload,'null'::jsonb)='null'::jsonb then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','roster_missing','rowKey',null,'message','No controlled-fleet roster has been saved.','blocking',true)); else
 global_findings:=global_findings||(version_payload->'findings');
if version_payload#>>'{dependencies,dependencySha256}' is distinct from deps->>'dependencySha256' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','dependency_stale','rowKey',null,'message','Corporate coverage or a mobile workpaper/review changed; save a current roster successor.','blocking',true)); end if;
if activity->>'coverageVersionId' is distinct from coverage->>'id' or activity->>'coverageVersionSha256' is distinct from coverage->>'versionSha256' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','coverage_stale','rowKey',null,'message','The roster is not bound to the current corporate coverage version.','blocking',true)); end if;
end if;
select coalesce(jsonb_agg(s order by n),'[]') into sources from jsonb_array_elements(coverage#>'{snapshot,sources}') with ordinality x(s,n) where s->>'domain'='mobile_combustion';
for asset in select a from jsonb_array_elements(coalesce(statement->'assets','[]'::jsonb)) with ordinality x(a,n) order by n loop
 row_key:='roster:'||(asset->>'rowId');
 select coalesce(jsonb_agg(f order by n),'[]') into findings from jsonb_array_elements(version_payload->'findings') with ordinality x(f,n) where f->>'rowKey'=row_key;
 select l->>'sourceId' into source_id from jsonb_array_elements(activity->'links') with ordinality x(l,n) where l->>'rowId'=asset->>'rowId' order by n desc limit 1;
 select s into source from jsonb_array_elements(sources) s where s->>'id'=source_id limit 1;
 select coalesce(jsonb_agg(w order by n),'[]') into works from jsonb_array_elements(workpapers) with ordinality x(w,n) where w#>>'{activity,binding,sourceId}'=source_id;
 if source_id is not null then mapped_sources:=array_append(mapped_sources,source_id);end if;
 for head in select w from jsonb_array_elements(works) w loop used_worksheets:=array_append(used_worksheets,head->>'worksheetId');end loop;
if source_id is not null and source is null then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_missing','rowKey',row_key,'message','The mapped source is absent from current corporate coverage.','blocking',true)); end if;
if source is not null and neuvetra.m75_source_eligible(coverage,source) is not true then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_ineligible','rowKey',row_key,'message','The current corporate mobile source or boundary is not eligible for M74.','blocking',true)); end if;
if source is not null then
 select s into screening from jsonb_array_elements(coverage#>'{snapshot,coverageItems}') with ordinality x(s,n) where s->>'sourceId'=source->>'id' and s->>'domain'='mobile_combustion' order by n limit 1;
if screening is null or screening->>'disposition' is distinct from 'included_activity' then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_screening_unresolved','rowKey',row_key,'message','The current corporate mobile-source screening must be included activity; missing, estimate, excluded and not-applicable assertions remain unresolved.','blocking',true)); end if;
end if;
if jsonb_array_length(works)=0 and source is not null then if jsonb_array_length(workpapers)>=3 then findings:=findings||jsonb_build_array(jsonb_build_object('code','capacity_blocked','rowKey',row_key,'message','The M74 three-workpaper capacity is full.','blocking',true)); else findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_missing','rowKey',row_key,'message','No current M74 workpaper exists for this vehicle.','blocking',true)); end if;end if;
if jsonb_array_length(works)>1 then findings:=findings||jsonb_build_array(jsonb_build_object('code','duplicate_workpaper','rowKey',row_key,'message','Multiple M74 workpapers map to this roster source.','blocking',true)); end if;
for head in select w from jsonb_array_elements(works) with ordinality x(w,n) order by n loop
if asset->'assetId' is distinct from head#>'{activity,vehicle,assetId}' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_asset_conflict','rowKey',row_key,'message','Roster and workpaper asset identities differ.','blocking',true)); end if;
if asset->'entityId' is distinct from head#>'{activity,binding,entityId}' or asset->'facilityId' is distinct from head#>'{activity,binding,facilityId}' or asset->'vehicleClass' is distinct from head#>'{activity,vehicle,vehicleClass}' or asset->'modelYear' is distinct from head#>'{activity,vehicle,modelYear}' or asset->'fuel' is distinct from head#>'{activity,vehicle,fuel}' or asset->'controlBasis' is distinct from head#>'{activity,vehicle,controlBasis}' or asset->'period' is distinct from head#>'{activity,period}' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_fact_conflict','rowKey',row_key,'message','Roster and workpaper boundary or vehicle facts differ.','blocking',true)); end if;
if coalesce(head->'calculation','null'::jsonb)='null'::jsonb or coalesce(head#>>'{activityStatus,fuel}','') not in('entered','explicit_zero') or coalesce(head#>>'{activityStatus,mileage}','') not in('entered','explicit_zero') or exists(select 1 from jsonb_array_elements(head->'findings') f where f->>'code' not in('scope1_incomplete','method_not_released')) then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_incomplete','rowKey',row_key,'message','The current workpaper has incomplete, discrepant or unsupported activity/evidence.','blocking',true)); end if;
if head#>>'{activity,binding,coverageVersionId}' is distinct from coverage->>'id' or head#>>'{activity,binding,coverageVersionSha256}' is distinct from coverage->>'versionSha256' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_stale','rowKey',row_key,'message','The workpaper is bound to an older corporate coverage version.','blocking',true)); end if;
if head#>>'{review,decision}' is distinct from 'accepted_bounded_internal' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_review_required','rowKey',row_key,'message','The exact current workpaper needs bounded internal acceptance.','blocking',true)); end if;
end loop;
select coalesce(jsonb_agg(w->'worksheetId' order by (w->>'worksheetId') collate "C"),'[]') into worksheet_ids from jsonb_array_elements(works) w;
select e->>'legalName' into entity_label from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=asset->>'entityId' limit 1;
select f->>'name' into facility_label from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=asset->>'facilityId' limit 1;
rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',asset->'rowId','sourceId',source_id,'assetId',asset->'assetId','worksheetIds',worksheet_ids,'entityLabel',entity_label,'facilityLabel',facility_label,'sourceLabel',source->>'name','status',neuvetra.m75_row_status(findings),'findings',findings));
end loop;
for source in select s from jsonb_array_elements(sources) with ordinality x(s,n) where not(s->>'id'=any(mapped_sources)) order by n loop
 row_key:='source:'||(source->>'id');findings:='[]';
findings:=findings||jsonb_build_array(jsonb_build_object('code','orphan_source','rowKey',row_key,'message','Current corporate mobile source is absent from the declared roster mapping.','blocking',true));
 select coalesce(jsonb_agg(w order by n),'[]') into works from jsonb_array_elements(workpapers) with ordinality x(w,n) where w#>>'{activity,binding,sourceId}'=source->>'id';
 for head in select w from jsonb_array_elements(works) w loop used_worksheets:=array_append(used_worksheets,head->>'worksheetId');end loop;
 select coalesce(jsonb_agg(w->'worksheetId' order by (w->>'worksheetId') collate "C"),'[]') into worksheet_ids from jsonb_array_elements(works) w;
 select e->>'legalName' into entity_label from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=source->>'entityId' limit 1;
 select f->>'name' into facility_label from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=source->>'facilityId' limit 1;
 rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',null,'sourceId',source->'id','assetId',works#>'{0,activity,vehicle,assetId}','worksheetIds',worksheet_ids,'entityLabel',entity_label,'facilityLabel',facility_label,'sourceLabel',source->>'name','status','orphan_source','findings',findings));
end loop;
for head in select w from jsonb_array_elements(workpapers) with ordinality x(w,n) where not(w->>'worksheetId'=any(used_worksheets)) order by n loop
 row_key:='workpaper:'||(head->>'worksheetId');findings:='[]';
findings:=findings||jsonb_build_array(jsonb_build_object('code','orphan_workpaper','rowKey',row_key,'message','Current M74 workpaper is absent from the declared roster mapping.','blocking',true));
 rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',null,'sourceId',head#>'{activity,binding,sourceId}','assetId',head#>'{activity,vehicle,assetId}','worksheetIds',jsonb_build_array(head->'worksheetId'),'entityLabel',null,'facilityLabel',null,'sourceLabel',null,'status','orphan_workpaper','findings',findings));
end loop;
select coalesce(jsonb_agg(r order by (r->>'rowKey') collate "C"),'[]') into rows_json from jsonb_array_elements(rows_json) r;
select global_findings||coalesce(jsonb_agg(f order by n,k),'[]') into all_findings from jsonb_array_elements(rows_json) with ordinality x(r,n) cross join lateral jsonb_array_elements(r->'findings') with ordinality y(f,k);
select r into current_review from jsonb_array_elements(reviews) with ordinality x(r,n) where r->>'versionId'=version_payload->>'id' and r->>'versionSha256'=version_payload->>'versionSha256' and r#>>'{dependencies,dependencySha256}'=deps->>'dependencySha256' order by n limit 1;
if current_review is null or current_review->>'decision' is distinct from 'accepted_bounded_reconciliation' then all_findings:=all_findings||jsonb_build_array(jsonb_build_object('code','roster_review_required','rowKey',null,'message','The exact current fleet reconciliation needs independent internal acceptance.','blocking',true)); end if;
final_status:=case when not exists(select 1 from jsonb_array_elements(all_findings) f where f->>'blocking'='true' and f->>'code'<>'roster_review_required') and current_review->>'decision'='accepted_bounded_reconciliation' then 'reconciled_bounded_synthetic' else 'blocked' end;
base:=jsonb_build_object('profile','m75-fleet-reconciliation-v1','companyId',target_company,'period',jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01'),
'rosterPin',case when coalesce(version_payload,'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',version_payload->'id','sha256',version_payload->'versionSha256') end,
'rosterReviewPin',case when current_review is null then 'null'::jsonb else jsonb_build_object('id',current_review->'id','sha256',current_review->'decisionSha256') end,
'coveragePin',deps->'coveragePin','coverageReviewPin',deps->'coverageReviewPin','workpaperPins',deps->'workpaperPins','rows',rows_json,'findings',all_findings,
'counts',jsonb_build_object('evidenceRows',jsonb_array_length(coalesce(statement->'assets','[]'::jsonb)),
'declaredUniqueKnownAssets',(select count(distinct a->>'assetId') from jsonb_array_elements(coalesce(statement->'assets','[]'::jsonb)) a where nullif(a->>'assetId','') is not null),
'currentMobileSources',jsonb_array_length(sources),'currentWorkpaperStreams',jsonb_array_length(workpapers),
'reconciledRows',(select count(*) from jsonb_array_elements(rows_json) r where r->>'status'='matched_reviewed'),
'blockingFindings',(select count(*) from jsonb_array_elements(all_findings) f where f->>'blocking'='true')),
'status',final_status,'dependencySha256',deps->>'dependencySha256',
'limitations','["synthetic_only","declared_roster_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb,
'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null);
return base||jsonb_build_object('contentSha256',neuvetra.m67_hash(base));
end $$;

create function neuvetra.m75_current_reconciliation(target_company uuid, review_override jsonb default null)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
declare coverage jsonb; workpapers jsonb; roster jsonb; reviews jsonb;
begin
select v.payload||jsonb_build_object('review',r.payload) into coverage from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.company_id=h.company_id and v.id=h.version_id left join neuvetra.corporate_inventory_reviews r on r.company_id=v.company_id and r.version_id=v.id where h.company_id=target_company;
select coalesce(jsonb_agg(v.payload||jsonb_build_object('review',r.payload) order by h.id),'[]') into workpapers from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on v.company_id=h.company_id and v.id=h.version_id left join neuvetra.mobile_diesel_reviews r on r.company_id=v.company_id and r.version_id=v.id where h.company_id=target_company;
select v.payload into roster from neuvetra.controlled_fleet_heads h join neuvetra.controlled_fleet_versions v on v.company_id=h.company_id and v.id=h.version_id where h.company_id=target_company;
select coalesce(jsonb_agg(r.payload order by r.reviewed_at,r.id),'[]') into reviews from neuvetra.controlled_fleet_reviews r where r.company_id=target_company;
if review_override is not null and review_override<>'null'::jsonb then reviews:=reviews||jsonb_build_array(review_override);end if;
return neuvetra.m75_derive_reconciliation(target_company,coverage,workpapers,roster,reviews);
end $$;

