create function neuvetra.review_controlled_fleet(target_company uuid,target_roster uuid,request jsonb,review_payload jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;old record;fingerprint text;deps jsonb;begin if not neuvetra.m75_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;if not neuvetra.m75_exact_keys(request,array['versionId','expectedVersionSha256','expectedDependencySha256','decision','note','acknowledgedLimitations','idempotencyKey']) or not neuvetra.m75_exact_keys(review_payload,array['id','versionId','versionSha256','dependencies','decision','note','acknowledgedLimitations','reviewerId','reviewedAt','decisionSha256']) or request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or request->>'expectedDependencySha256'!~'^[0-9a-f]{64}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or review_payload->>'id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or review_payload->>'reviewerId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or review_payload->>'reviewedAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z$' or review_payload->>'decisionSha256'!~'^[0-9a-f]{64}$' or request->>'decision' is null or request->>'decision' not in('accepted_bounded_reconciliation','changes_requested') or neuvetra.m75_text_valid(request->'note',500) is not true or request->'acknowledgedLimitations' is distinct from '["synthetic_only","declared_roster_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb then raise exception 'invalid review request' using errcode='22023';end if;deps:=neuvetra.m75_current_dependencies(target_company);if request->>'expectedDependencySha256' is distinct from deps->>'dependencySha256' then raise exception 'review dependencies changed' using errcode='23505';end if;fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'rosterId',target_roster,'request',request-'idempotencyKey'));select * into old from neuvetra.controlled_fleet_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'review' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;select vv.* into v from neuvetra.controlled_fleet_heads h join neuvetra.controlled_fleet_versions vv on vv.company_id=h.company_id and vv.id=h.version_id where h.company_id=target_company and h.id=target_roster and vv.id=(request->>'versionId')::uuid;if not found or v.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'review conflict' using errcode='23505';end if;if exists(select 1 from jsonb_array_elements_text(v.payload->'contributorIds')x where x=actor::text) then raise exception 'contributors cannot review' using errcode='42501';end if;if request->>'decision'='accepted_bounded_reconciliation' and (neuvetra.m75_current_reconciliation(target_company,review_payload)#>>'{status}') is distinct from 'reconciled_bounded_synthetic' then raise exception 'blocked reconciliation cannot be accepted' using errcode='22023';end if;if review_payload->>'reviewerId' is distinct from actor::text or review_payload->>'versionId' is distinct from v.id::text or review_payload->>'versionSha256' is distinct from v.version_sha256 or review_payload->'dependencies' is distinct from deps or v.payload->'dependencies' is distinct from deps or review_payload->'decision' is distinct from request->'decision' or review_payload->'note' is distinct from r